// Some mistakes stop the program: try/catch captures them.
const user = null;
try {
  console.log(user.name); // reading a property of null fails
} catch (error) {
  console.log("Caught:", error.name, "-", error.message);
}

function safeParse(text) {
  try {
    return JSON.parse(text); // throws if the text is not valid JSON
  } catch (error) {
    console.log(`Not valid JSON: ${text}`);
    return null;
  } finally {
    console.log("  (finally always runs)");
  }
}
console.log(safeParse('{"stock": 5}'));
console.log(safeParse("{stock: 5}"));

// throw raises your own error when the data is wrong.
function withdraw(balance, amount) {
  if (amount <= 0) throw new Error("the amount must be positive");
  if (amount > balance) throw new RangeError(`only ${balance} euros left`);
  return balance - amount;
}
for (const amount of [30, -10, 500]) {
  try {
    console.log(`Withdraw ${amount}: balance ${withdraw(100, amount)}`);
  } catch (error) {
    console.log(`Withdraw ${amount} failed: ${error.message} (${error.name})`);
  }
}

// Read everything typed on the keyboard (stdin) as one string.
const fs = require("fs");
const input = fs.readFileSync(0, "utf8");

// Split it into lines and drop the empty ones.
const lines = input.split("\n").map((l) => l.trim()).filter((l) => l !== "");
console.log(`Read ${lines.length} lines`);

// Each line has a name and a grade separated by a space.
const students = [];
for (const line of lines) {
  const [name, gradeText] = line.split(" ");
  const grade = Number(gradeText);
  if (Number.isNaN(grade)) {
    console.log(`Skipping "${line}": the grade is not a number`);
    continue;
  }
  students.push({ name, grade });
}

// A small report with what we have read.
for (const { name, grade } of students) {
  const result = grade >= 5 ? "passed" : "failed";
  console.log(`${name.padEnd(6)} ${grade.toFixed(2).padStart(5)}  ${result}`);
}
const sum = students.reduce((acc, s) => acc + s.grade, 0);
console.log("Class average:", (sum / students.length).toFixed(2));

// A small to-do list driven by text commands.
const commands = ["add Buy milk", "add Call the dentist", "add Water the plants",
  "done 1", "remove 2", "done 7", "add Finish the JavaScript course", "jump 3"];

const tasks = [];
let nextId = 1;

function run(line) {
  const [command, ...words] = line.split(" ");
  const text = words.join(" ");
  if (command === "add") {
    tasks.push({ id: nextId, title: text, done: false });
    return `added #${nextId++} "${text}"`;
  }
  const task = tasks.find((t) => t.id === Number(text));
  if (!task) throw new Error(`there is no task #${text}`);
  if (command === "done") task.done = true;
  else if (command === "remove") tasks.splice(tasks.indexOf(task), 1);
  else throw new Error(`unknown command "${command}"`);
  return `${command} #${task.id}`;
}

for (const line of commands) {
  try { console.log("ok   ", run(line)); }
  catch (error) { console.log("error", error.message); }
}

for (const { id, title, done } of tasks) {
  console.log(`${done ? "[x]" : "[ ]"} ${String(id).padStart(2)}  ${title}`);
}
const pending = tasks.filter((t) => !t.done).length;
console.log(`${tasks.length} tasks, ${pending} pending`);
console.log("Saved as JSON:", JSON.stringify(tasks).length, "characters");

