// Each call to createCounter gets its own private "count".
function createCounter(label) {
  let count = 0; // lives on inside the closure
  return function next() {
    count += 1;
    return `${label} #${count}`;
  };
}

const nextOrder = createCounter("Order");
const nextInvoice = createCounter("Invoice");
console.log(nextOrder());
console.log(nextOrder());
console.log(nextInvoice());
console.log(nextOrder());

// Block scope: let creates a new binding on every loop turn.
const tasks = [];
for (let i = 1; i <= 3; i++) {
  tasks.push(() => `task ${i}`);
}
console.log(tasks.map((run) => run()).join(", "));

// A closure can also keep settings, such as a discount rate.
function makeDiscount(rate) {
  return (price) => +(price * (1 - rate)).toFixed(2);
}
const blackFriday = makeDiscount(0.3);
console.log("Black Friday price:", blackFriday(49.9));
console.log("Is count visible here?", typeof count);

const cart = {
  owner: "Ana",
  items: [12.5, 30, 7.25],
  total() {
    return this.items.reduce((sum, price) => sum + price, 0);
  },
  describe() {
    return `${this.owner} owes ${this.total().toFixed(2)} EUR`;
  },
  // An arrow function has no "this" of its own: it uses the method's one.
  labels() {
    return this.items.map((price) => `${this.owner}:${price}`);
  },
};
console.log(cart.describe());
console.log(cart.labels().join(" "));

// Losing "this": the method is called without its object.
const loose = cart.describe;
try { loose(); } catch (err) { console.log("Lost this:", err.message); }

// bind returns a new function with "this" fixed for good.
const bound = cart.describe.bind(cart);
console.log("bind:", bound());

// call and apply run the function now with the "this" you choose.
const otherCart = { owner: "Luis", items: [5, 5], total: cart.total };
console.log("call:", cart.describe.call(otherCart));
function withTax(rate, label) {
  return `${label}: ${(this.total() * (1 + rate)).toFixed(2)} EUR`;
}
console.log(withTax.call(cart, 0.21, "Ana with VAT"));
console.log(withTax.apply(otherCart, [0.1, "Luis with 10%"]));

const product = {
  describe() {
    return `${this.name} - ${this.price.toFixed(2)} EUR`;
  },
};

// laptop's prototype is product, so it inherits describe().
const laptop = Object.create(product);
laptop.name = "Laptop";
laptop.price = 899;
console.log(laptop.describe());
console.log("Own describe?", Object.hasOwn(laptop, "describe"));
console.log("Prototype is product?", Object.getPrototypeOf(laptop) === product);

// Constructor functions share methods through .prototype.
function User(name, role) {
  this.name = name;
  this.role = role;
